WITH eng_courses AS ( SELECT t0.COURSE_DESCRIPTION, t1.DEPARTMENT_NAME, t1.DEPARTMENT_CODE, dense_rank() OVER (ORDER BY t1.DEPT_BUDGET_CODE ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS window_column FROM SIS_COURSE_DESCRIPTION t0 JOIN SIS_DEPARTMENT t1 ON t0.DEPARTMENT = t1.DEPARTMENT_CODE WHERE t1.SCHOOL_NAME = 'Engineering' AND t1.IS_DEGREE_GRANTING = 'Y' ), term_params AS ( SELECT t0.TERM_PARAMETER, t0.TERM_CODE, t1.ACADEMIC_YEAR, t2.DEPARTMENT_NAME, t2.DEPARTMENT_CODE, SUM(t1.ACADEMIC_YEAR) OVER (PARTITION BY t2.DEPARTMENT_NAME ORDER BY t1.ACADEMIC_YEAR) AS window_column FROM ACADEMIC_TERM_PARAMETER t0 JOIN ACADEMIC_TERMS t1 ON t0.TERM_CODE = t1.TERM_CODE JOIN COURSE_CATALOG_SUBJECT_OFFERED t2 ON t1.TERM_CODE = t2.EFFECTIVE_TERM_CODE WHERE t0.TERM_INDICATOR = 'C' ) SELECT ec.COURSE_DESCRIPTION, ec.DEPARTMENT_NAME AS ENG_DEPARTMENT_NAME, ec.window_column AS ENG_DEPT_DENSE_RANK, tp.TERM_PARAMETER, tp.TERM_CODE, tp.ACADEMIC_YEAR, tp.DEPARTMENT_NAME AS OFFERED_DEPARTMENT_NAME, tp.window_column AS DEPT_RUNNING_SUM_ACAD_YEAR FROM eng_courses ec JOIN term_params tp ON ec.DEPARTMENT_CODE = tp.DEPARTMENT_CODE ORDER BY ec.DEPARTMENT_NAME, tp.ACADEMIC_YEAR